const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Polygon([[
        [142.06, -32.53],
        [142.06, -32.22],
        [142.66, -32.22],
        [142.66, -32.53]
    ]]);

    const dateT1 = ee.Date('2019-02-02');
    const dateT2 = ee.Date('2021-05-14');

    // Use a +/- 30 day window to find a clear image
    const dateRangeT1 = ee.DateRange(dateT1.advance(-30, 'day'), dateT1.advance(30, 'day'));
    const dateRangeT2 = ee.DateRange(dateT2.advance(-30, 'day'), dateT2.advance(30, 'day'));

    // 2. Data Acquisition & Pre-processing
    const S2_SR_COLLECTION_NAME = 'COPERNICUS/S2_SR_HARMONIZED';

    // Cloud masking function for Sentinel-2
    function maskS2clouds(image) {
        const qa = image.select('QA60');
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(
            qa.bitwiseAnd(cirrusBitMask).eq(0));
        return image.updateMask(mask).divide(10000).copyProperties(image, ["system:time_start"]);
    }

    // Function to calculate water area
    const getWaterArea = (image) => {
        // MNDWI = (Green - SWIR1) / (Green + SWIR1)
        // Sentinel-2 Bands: Green=B3, SWIR1=B11
        const mndwi = image.normalizedDifference(['B3', 'B11']).rename('mndwi');
        const water = mndwi.gt(0); // Threshold to identify water
        const waterAreaImage = water.multiply(ee.Image.pixelArea());

        const stats = waterAreaImage.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: geometry,
            scale: 1000,
            maxPixels: 1e12
        });
        return ee.Number(stats.get('mndwi')).divide(1e6); // Convert area to sq km
    };

    // 3. Processing and Calculation
    const collectionT1 = ee.ImageCollection(S2_SR_COLLECTION_NAME)
        .filterBounds(geometry)
        .filterDate(dateRangeT1)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

    const collectionT2 = ee.ImageCollection(S2_SR_COLLECTION_NAME)
        .filterBounds(geometry)
        .filterDate(dateRangeT2)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));

    const sizeT1 = collectionT1.size().getInfo();
    const sizeT2 = collectionT2.size().getInfo();

    if (sizeT1 === 0 || sizeT2 === 0) {
        console.log(`Image count 2019: ${sizeT1}`);
        console.log(`Image count 2021: ${sizeT2}`);
        console.log('C1');
        return;
    }

    const imageT1 = collectionT1.map(maskS2clouds).median();
    const imageT2 = collectionT2.map(maskS2clouds).median();

    const waterAreaT1 = getWaterArea(imageT1);
    const waterAreaT2 = getWaterArea(imageT2);

    // 4. Validation & Final Answer
    const area1 = waterAreaT1.getInfo();
    const area2 = waterAreaT2.getInfo();

    if (area1 === null || area2 === null) {
        console.log(`2019 Area (km2): ${area1}`);
        console.log(`2021 Area (km2): ${area2}`);
        console.log('C3');
        return;
    }

    // Check if valid pixels existed by seeing if the area is zero. 
    // It's highly improbable for the entire lake system to have 0 water area.
    if (area1 <= 0 && area2 <= 0) {
        console.log('Both periods returned zero or negative water area.');
        console.log('C2');
        return;
    }


    console.log(`Lake Menindee Water Area 2019 (km2): ${area1.toFixed(2)}`);
    console.log(`Lake Menindee Water Area 2021 (km2): ${area2.toFixed(2)}`);

    if (area2 < area1) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during Earth Engine initialization or analysis.');
        console.error(e);
        console.log('D');
    }
}

initEE();
